package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** Sets the imported rates in order, each exactly as the rate form would: RATE_SET, then the figures it moved. */
public class SaveImportRates {
    public void save(@PathVariable("sheetId") String sheetId, @Val ValidImportRates request, Rates rates, Audit audit, Rollup rollup,
            ObjectResponse<ImportRatesResponse> response) {
        for (ValidRate rate : request.rates()) {
            RollupFigures before = rollup.figures(sheetId);
            SetRate.apply(sheetId, rate, rates, audit);
            rollup.recordChanges(sheetId, request.user(), before);
        }
        response.send(new ImportRatesResponse(request.rates().size()));
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.Audit;

/** Setting one valid rate, as the rate form and the rate import both do. */
final class SetRate {
    private SetRate() {
    }

    /** Set the rate, replacing one for the same grade and from-date, and audit it as RATE_SET (on commit). */
    static void apply(String sheetId, ValidRate rate, Rates rates, Audit audit) {
        rates.set(sheetId, rate.grade(), rate.from(), rate.to(), rate.rate());
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + rate.user()
                + " grade=" + rate.grade() + " rate=" + rate.rate().toPlainString()
                + (rate.from() == null ? "" : " from=" + rate.from())
                + (rate.to() == null ? "" : " to=" + rate.to()));
    }
}
package net.officefloor.hq.app.rate;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveRate {
    public void save(@PathVariable("sheetId") String sheetId, @Val ValidRate rate, Rates rates, Audit audit, @Val RollupFigures before, Rollup rollup,
            ObjectResponse<List<RateResponse>> response) {
        SetRate.apply(sheetId, rate, rates, audit);
        rollup.recordChanges(sheetId, rate.user(), before);
        response.send(rates.list(sheetId));
    }

}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.asof.AsOfView;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The rates of the sheet's parent, its parent's parent and so on (up to three levels up), nearest
 *  first; with an as-of date, each as it stood at the end of it. */
public class LoadInheritedRates {
    public void service(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "asOf", required = false) String asOf, Rates rates, AsOfView view,
            ObjectResponse<List<List<RateResponse>>> response) {
        LocalDate date = AsOfView.parse(asOf);
        response.send(date == null ? rates.inherited(sheetId)
                : rates.ancestors(sheetId).stream().map(ancestor -> view.rates(ancestor, date)).toList());
    }
}
